class Solution {
    public int minSwaps(String s){
        int balance=0,minimum=0;
        for(char value:s.toCharArray()){
            balance+=value=='['?1:-1;
            minimum=Math.min(minimum,balance);
        }
        return (-minimum+1)/2;
    }
}

code.kotlin:
class Solution {
    fun minSwaps(s:String):Int{
        var balance=0;
        var minimum=0;
        for(value in s){
            balance+=if(value=='[')1 else -1;
            minimum=minOf(minimum,balance)
        };
        return (-minimum+1)/2
    }
}

